'use strict'
// Real TypeScript check (esbuild only strips types, so mismatched props / missing fields slip through it).
const fs = require('fs')
const path = require('path')
const { execFile } = require('child_process')
const { importedPackages, installed } = require('./workspace')

const TSC = path.join(__dirname, '..', 'node_modules', 'typescript', 'bin', 'tsc')

function runTypecheck(ws, files, timeoutMs = 45000) {
  const packages = importedPackages(files)
  const missing = packages.filter((pkg) => !installed(pkg))
  const shims = [
    '// generated by vibe-qa',
    'declare module "*.css";',
    'declare module "*.svg";',
    'declare module "*.png";',
    'declare module "*.jpg";',
    'declare module "*.json";',
    'interface Window { GolinelliAI: any; GolinelliML: any; [key: string]: any }',
    ...missing.flatMap((pkg) => [`declare module "${pkg}";`, `declare module "${pkg}/*";`]),
  ].join('\n')
  fs.writeFileSync(path.join(ws.root, 'qa-shims.d.ts'), shims)
  fs.writeFileSync(path.join(ws.root, 'tsconfig.json'), JSON.stringify({
    compilerOptions: {
      target: 'ES2020', module: 'ESNext', moduleResolution: 'bundler', jsx: 'react-jsx',
      lib: ['DOM', 'DOM.Iterable', 'ES2022'], noEmit: true, skipLibCheck: true,
      strict: false, strictNullChecks: true, noImplicitAny: false, allowJs: false,
      esModuleInterop: true, resolveJsonModule: true, isolatedModules: true, types: [],
      forceConsistentCasingInFileNames: true,
    },
    include: ['**/*.ts', '**/*.tsx', 'qa-shims.d.ts'],
    exclude: ['node_modules'],
  }))
  return new Promise((resolve) => {
    execFile('node', [TSC, '-p', 'tsconfig.json', '--pretty', 'false'], { cwd: ws.root, timeout: timeoutMs, maxBuffer: 8 * 1024 * 1024 }, (err, stdout, stderr) => {
      if (err && err.killed) return resolve({ ran: false, reason: 'timeout', errors: [], missingTypes: missing })
      const errors = []
      const re = /^(.+?)\((\d+),(\d+)\): error (TS\d+): (.+)$/
      for (const line of String(stdout || '').split('\n')) {
        const m = re.exec(line.trim())
        if (!m) continue
        const file = m[1].replace(/\\/g, '/')
        if (file.startsWith('node_modules') || file === 'qa-shims.d.ts') continue
        errors.push({ file, line: Number(m[2]), col: Number(m[3]), code: m[4], message: m[5].slice(0, 300) })
      }
      resolve({ ran: true, errors: errors.slice(0, 40), total: errors.length, missingTypes: missing })
    })
  })
}

module.exports = { runTypecheck }
